import subprocess, os, shutil, pathlib
def genwarn(name, ports):
    # ports: list of list of (inlabel,outlabel or None for normal) labels empty messages named label, normal messages INORM/ONORM
    msgs={}
    wsdl='<?xml version="1.0"?><wsdl:definitions xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:tns="urn:t" targetNamespace="urn:t">'
    wsdl+='<wsdl:types><xsd:schema targetNamespace="urn:t"><xsd:element name="Req" type="xsd:string"/><xsd:element name="Resp" type="xsd:string"/></xsd:schema></wsdl:types>'
    wsdl+='<wsdl:message name="NIN"><wsdl:part name="p" element="tns:Req"/></wsdl:message><wsdl:message name="NOUT"><wsdl:part name="p" element="tns:Resp"/></wsdl:message>'
    for ops in ports:
        for a,b in ops:
            for lab in (a,b):
                if lab and lab not in msgs:
                    msgs[lab]=1; wsdl+=f'<wsdl:message name="{lab}"></wsdl:message>'
    for pi,ops in enumerate(ports):
        wsdl+=f'<wsdl:portType name="P{pi}">'
        for oi,(a,b) in enumerate(ops):
            wsdl+=f'<wsdl:operation name="Op{pi}_{oi}"><wsdl:input message="tns:{a or "NIN"}"/><wsdl:output message="tns:{b or "NOUT"}"/></wsdl:operation>'
        wsdl+='</wsdl:portType>'
    wsdl+='</wsdl:definitions>'
    d=f"/tmp/wp_{name}"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d+"/out"); pathlib.Path(d+"/in.wsdl").write_text(wsdl)
    r=subprocess.run(["/workspace/executable",d+"/in.wsdl"],cwd=d+"/out",capture_output=True,text=True)
    w=[l.split("[WARN] ")[1].split(" message")[0] for l in r.stdout.splitlines() if "[WARN]" in l]
    print(name,w)
for n in range(1,6):
    genwarn(f"inputs{n}",[[(f"I{i}",None) for i in range(n)]])
for n in range(1,5):
    genwarn(f"outputs{n}",[[(None,f"O{i}") for i in range(n)]])
for n in range(1,5):
    genwarn(f"both{n}",[[(f"I{i}",f"O{i}") for i in range(n)]])
