import subprocess, os, shutil, pathlib
# package dir is a file
for setup in ["file","readonlydir","existingfiles"]:
    d=f"/tmp/dir_{setup}"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    if setup=="file": pathlib.Path(d,"myservice").write_text("hi")
