    if setup=="existingfiles": os.mkdir(d+"/myservice"); pathlib.Path(d+"/myservice/myservice.go").write_text("old"); pathlib.Path(d+"/myservice/servermyservice.go").write_text("oldserver")
    r=subprocess.run(["/workspace/executable","/workspace/assets/stock.wsdl"],cwd=d,capture_output=True,text=True)
