    for p in pathlib.Path(d).rglob("*"): print(p.relative_to(d), oct(p.stat().st_mode & 0o777), p.read_text()[:30] if p.is_file() else "")
    if setup=="readonlydir": os.chmod(d+"/myservice",0o755)
PY"}

