package main

import (
	"go/token"
	"strings"
	"unicode"
)

func sanitizeIdent(s string) string {
	s = strings.ReplaceAll(s, "@", "At")
	s = strings.ReplaceAll(s, "+", "Plus")
	s = strings.ReplaceAll(s, "-", "_")
	s = strings.ReplaceAll(s, ".", "_")
	var b strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func capFirst(s string) string {
	if s == "" {
		return s
	}
	rs := []rune(s)
	rs[0] = unicode.ToUpper(rs[0])
	return string(rs)
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	rs := []rune(s)
	rs[0] = unicode.ToLower(rs[0])
	return string(rs)
}

var lowerBuiltin = map[string]bool{
	"bool": true, "byte": true,
	"float32": true, "float64": true,
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"string": true, "uint16": true, "uint32": true,
}

// declaredName applies the configurable public/private naming transform
// used for declared Go types, enum values, field names in anonymous
// structures and operation argument types.
func (g *generator) declaredName(s string) string {
	return declaredWith(s, g.makePublic)
}

func declaredWith(s string, public bool) string {
	san := sanitizeIdent(s)
	if public {
		if token.IsKeyword(s) {
			return capFirst(san) + "_"
		}
		if san == "" {
			return "EmptyString"
		}
		if lowerBuiltin[san] {
			return san
		}
		return capFirst(san)
	}
	if token.IsKeyword(s) {
		return san + "_"
	}
	return san
}

func declaredPublic(s string) string { return declaredWith(s, true) }

func typedFieldName(s string) string {
	if s == "string" {
		return "Astring"
	}
	return declaredPublic(s)
}

func attrFieldName(s string) string {
	san := sanitizeIdent(s)
	if san == "" {
		return "EmptyString"
	}
	if lowerBuiltin[san] {
		return san
	}
	return capFirst(san)
}

func stripQName(s string) string {
	parts := strings.Split(s, ":")
	if len(parts) == 2 {
		return parts[1]
	}
	return parts[0]
}

var xsdTypeMap = map[string]string{
	"string":             "string",
	"boolean":            "bool",
	"decimal":            "float64",
	"float":              "float32",
	"double":             "float64",
	"datetime":           "soap.XSDDateTime",
	"time":               "soap.XSDTime",
	"date":               "soap.XSDDate",
	"hexbinary":          "[]byte",
	"base64binary":       "[]byte",
	"token":              "string",
	"integer":            "int32",
	"int":                "int32",
	"long":               "int64",
	"short":              "int16",
	"byte":               "int8",
	"nonnegativeinteger": "uint32",
	"unsignedlong":       "uint64",
	"unsignedint":        "uint32",
	"unsignedshort":      "uint16",
	"unsignedbyte":       "byte",
	"anytype":            "AnyType",
	"anyuri":             "AnyURI",
	"ncname":             "NCName",
}

// plainGoType maps a QName to a Go type without pointer/list decorations.
func plainGoType(qname string) string {
	local := stripQName(qname)
	if mapped, ok := xsdTypeMap[strings.ToLower(local)]; ok {
		return mapped
	}
	san := sanitizeIdent(local)
	if san == "" {
		return "EmptyString"
	}
	if lowerBuiltin[san] {
		return san
	}
	return capFirst(san)
}

// fieldGoType applies pointer (for custom/nillable types) and slice rules.
func fieldGoType(qname string, nillable bool, maxOccurs string) string {
	local := stripQName(qname)
	var core string
	if mapped, ok := xsdTypeMap[strings.ToLower(local)]; ok {
		core = mapped
	} else {
		core = "*" + plainGoType(local)
	}
	if nillable && !strings.HasPrefix(core, "*") {
		core = "*" + core
	}
	if maxOccurs == "unbounded" {
		core = "[]" + core
	}
	return core
}

func fieldGoTypeNoOcc(qname string) string { return fieldGoType(qname, false, "") }

func (g *generator) opMethodName(s string) string {
	var t string
	if g.makePublic {
		if s == "" {
			t = "EmptyString"
		} else if lowerBuiltin[s] {
			t = s
		} else {
			t = capFirst(s)
		}
	} else {
		if token.IsKeyword(s) {
			t = s + "_"
		} else {
			t = s
		}
	}
	return sanitizeIdent(t)
}

func (g *generator) portInterfaceName(s string) string {
	if !g.makePublic {
		return s
	}
	if s == "" {
		return "EmptyString"
	}
	if lowerBuiltin[s] {
		return s
	}
	return capFirst(s)
}
EOF
gofmt -w /workspace/names.go"}

