package main

const wsdlNS = "http://schemas.xmlsoap.org/wsdl/"
const xsdNS = "http://www.w3.org/2001/XMLSchema"
const soapNS = "http://schemas.xmlsoap.org/wsdl/soap/"

type Definitions struct {
	Types     *Types      `xml:"http://schemas.xmlsoap.org/wsdl/ types"`
	Messages  []*Message  `xml:"http://schemas.xmlsoap.org/wsdl/ message"`
	PortTypes []*PortType `xml:"http://schemas.xmlsoap.org/wsdl/ portType"`
	Bindings  []*Binding  `xml:"http://schemas.xmlsoap.org/wsdl/ binding"`
}

type Types struct {
	Schemas []*Schema `xml:"http://www.w3.org/2001/XMLSchema schema"`
}

type Message struct {
	Name  string       `xml:"name,attr"`
	Parts []*Part      `xml:"http://schemas.xmlsoap.org/wsdl/ part"`
}

type Part struct {
	Name    string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type    string `xml:"type,attr"`
}

type PortType struct {
	Name       string       `xml:"name,attr"`
	Operations []*Operation `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
}

type Operation struct {
	Name          string    `xml:"name,attr"`
	Documentation string    `xml:"http://schemas.xmlsoap.org/wsdl/ documentation"`
	Input         OpInput   `xml:"http://schemas.xmlsoap.org/wsdl/ input"`
	Output        OpInput   `xml:"http://schemas.xmlsoap.org/wsdl/ output"`
	Faults        []*Fault  `xml:"http://schemas.xmlsoap.org/wsdl/ fault"`
}

type OpInput struct {
	Message string `xml:"message,attr"`
}

type Fault struct {
	Name    string `xml:"name,attr"`
	Message string `xml:"message,attr"`
}

type Binding struct {
	Name       string             `xml:"name,attr"`
	Type       string             `xml:"type,attr"`
	Operations []*BindingOperation `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
}

type BindingOperation struct {
	Name          string         `xml:"name,attr"`
	SoapOperation *SoapOperation `xml:"http://schemas.xmlsoap.org/wsdl/soap/ operation"`
}

type SoapOperation struct {
	SoapAction string `xml:"soapAction,attr"`
}

type Schema struct {
	TargetNamespace string          `xml:"targetNamespace,attr"`
	Imports         []*SchemaImport `xml:"http://www.w3.org/2001/XMLSchema import"`
	Includes        []*SchemaImport `xml:"http://www.w3.org/2001/XMLSchema include"`
	SimpleTypes     []*SimpleType   `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
	Elements        []*XElement     `xml:"http://www.w3.org/2001/XMLSchema element"`
	ComplexTypes    []*ComplexType  `xml:"http://www.w3.org/2001/XMLSchema complexType"`
	Attributes      []*XAttribute   `xml:"http://www.w3.org/2001/XMLSchema attribute"`
}

type SchemaImport struct {
	Namespace      string `xml:"namespace,attr"`
	SchemaLocation string `xml:"schemaLocation,attr"`
}

type Annotation struct {
	Documentation string `xml:"http://www.w3.org/2001/XMLSchema documentation"`
}

func annotationDoc(a *Annotation) string {
	if a == nil {
		return ""
	}
	return a.Documentation
}

type XElement struct {
	Name        string       `xml:"name,attr"`
	Type        string       `xml:"type,attr"`
	Ref         string       `xml:"ref,attr"`
	MinOccurs   string       `xml:"minOccurs,attr"`
	MaxOccurs   string       `xml:"maxOccurs,attr"`
	Nillable    bool         `xml:"nillable,attr"`
	Annotation  *Annotation  `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	ComplexType *ComplexType `xml:"http://www.w3.org/2001/XMLSchema complexType"`
	SimpleType  *SimpleType  `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
}

type XAttribute struct {
	Name       string      `xml:"name,attr"`
