{"command":"cat > /workspace/main.go << 'EOF'
package main

import (
	"crypto/tls"
	"encoding/xml"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
)

func logLine(v interface{}) {
	fmt.Printf("🍀  %v\n", v)
}

func main() {
	outputDir := flag.String("d", "./", "Directory under which package directory will be created")
	ignoreTLS := flag.Bool("i", false, "Skips TLS Verification")
	makePublic := flag.Bool("make-public", true, "Make the generated types public/exported")
	outputFile := flag.String("o", "myservice.go", "File where the generated code will be saved")
	pkg := flag.String("p", "myservice", "Package under which code will be generated")
	showVersion := flag.Bool("v", false, "Shows gowsdl version")

	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "Usage: %s [options] myservice.wsdl\n", os.Args[0])
		flag.PrintDefaults()
	}

	if len(os.Args) < 2 {
		flag.Usage()
		return
	}
	flag.Parse()

	if *showVersion {
		logLine("v0.5.0")
		return
	}

	input := os.Args[len(os.Args)-1]
	g, err := loadGenerator(input, *pkg, *makePublic, *ignoreTLS)
	if err != nil {
		logLine(err)
		os.Exit(1)
	}
	if err := g.generate(*outputDir, *outputFile); err != nil {
		logLine(err)
		os.Exit(1)
	}
	logLine("Done 👍")
}

type generator struct {
	pkg        string
	makePublic bool
	client     *http.Client
	defs       *Definitions
	raw        []byte
	schemas    []*Schema
	visited    map[string]bool
	xmlNames   map[*ComplexType]string
	ports      []*resolvedPort
	allOps     []*resolvedOp
}

type fileLocation struct {
	remote bool
	url    *url.URL
	path   string
}

func (l *fileLocation) String() string {
	if l.remote {
		return l.url.String()
	}
	return l.path
}

func parseLocation(raw string) *fileLocation {
	u, _ := url.Parse(raw)
	scheme := u.Scheme
	if scheme != "" {
		return &fileLocation{remote: true, url: u}
	}
	abs, _ := filepath.Abs(raw)
	return &fileLocation{path: abs}
}

func resolveLocation(base *fileLocation, raw string) *fileLocation {
	u, _ := url.Parse(raw)
	scheme := u.Scheme
	if scheme != "" {
		return &fileLocation{remote: true, url: u}
	}
	if base.remote {
		return &fileLocation{remote: true, url: base.url.ResolveReference(u)}
	}
	if filepath.IsAbs(raw) {
		return &fileLocation{path: filepath.Clean(raw)}
	}
	return &fileLocation{path: filepath.Join(filepath.Dir(base.path), raw)}
}

func (g *generator) readLocation(loc *fileLocation) ([]byte, error) {
	if loc.remote {
		logLine("Downloading file " + loc.String())
		resp, err := g.client.Get(loc.url.String())
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return nil, fmt.Errorf("Received response code %d", resp.StatusCode)
		}
		return io.ReadAll(resp.Body)
	}
	logLine("Reading file " + loc.String())
	return os.ReadFile(loc.path)
}

func loadGenerator(input string, pkg string, makePublic bool, ignoreTLS bool) (*generator, error) {
	client := http.DefaultClient
	if ignoreTLS {
		transport := http.DefaultTransport.(*http.Transport).Clone()
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
		client = &http.Client{Transport: transport}
	}
	g := &generator{
		pkg:        pkg,
		makePublic: makePublic,
		client:     client,
		visited:    make(map[string]bool),
		xmlNames:   make(map[*ComplexType]string),
	}
	loc := parseLocation(input)
	raw, err := g.readLocation(loc)
	if err != nil {
		return nil, err
	}
	g.raw = raw
	var defs Definitions
	if err := xml.Unmarshal(raw, &defs); err != nil {
		return nil, err
	}
	g.defs = &defs
	var initial []*Schema
	if defs.Types != nil {
		initial = defs.Types.Schemas
	}
	g.schemas = append(g.schemas, initial...)
	for _, sch := range initial {
		if err := g.processSchemaImports(sch, loc); err != nil {
			return nil, err
		}
	}
	g.computeXMLNames()
	g.emitOperationWarnings()
	g.buildOperations()
	return g, nil
}

func (g *generator) processSchemaImports(sch *Schema, base *fileLocation) error {
	for _, imp := range sch.Imports {
		if imp.SchemaLocation == "" {
			logLine("[WARN] Don't know where to find XSD for " + imp.Namespace)
			continue
		}
		if err := g.loadExternal(base, imp.SchemaLocation); err != nil {
			return err
		}
	}
	for _, inc := range sch.Includes {
		if err := g.loadExternal(base, inc.SchemaLocation); err != nil {
			return err
		}
	}
	return nil
}

func (g *generator) loadExternal(base *fileLocation, raw string) error {
	loc := resolveLocation(base, raw)
	key := loc.String()
	if g.visited[key] {
		return nil
	}
	g.visited[key] = true
	data, err := g.readLocation(loc)
	if err != nil {
		return err
	}
	var sch Schema
	if err := xml.Unmarshal(data, &sch); err != nil {
		return err
	}
	if err := g.processSchemaImports(&sch, loc); err != nil {
		return err
	}
	g.schemas = append(g.schemas, &sch)
	return nil
}
EOF
gofmt -w /workspace/main.go"}

