	}
	return nil
}

func (g *generator) findGlobalElement(name string) *XElement {
	for _, sch := range g.schemas {
		for _, el := range sch.Elements {
			if el.Name == name {
				return el
			}
		}
	}
	return nil
}

func (g *generator) findGlobalAttribute(name string) *XAttribute {
	for _, sch := range g.schemas {
		for _, at := range sch.Attributes {
			if at.Name == name {
				return at
			}
		}
	}
	return nil
}

func (g *generator) resolveMessageType(ref string, warn bool) string {
	msg := g.findMessage(ref, warn)
	if msg == nil {
		return ""
	}
	part := msg.Parts[0]
	if part.Type != "" {
		return stripQName(part.Type)
	}
	el := g.findGlobalElement(stripQName(part.Element))
	if el == nil {
		return ""
	}
	if el.Type != "" {
		return stripQName(el.Type)
	}
	return el.Name
}

// emitOperationWarnings reproduces the sequence of message lookups that
// occurs while the reference generator pre-computes operations (global
// passes followed by two passes per port).
func (g *generator) emitOperationWarnings() {
	// Global pass: inputs only.
	for _, pt := range g.defs.PortTypes {
		for _, op := range pt.Operations {
			_ = g.resolveMessageType(op.Input.Message, true)
		}
	}
	// Global pass: output then input per operation.
	for _, pt := range g.defs.PortTypes {
		for _, op := range pt.Operations {
			_ = g.resolveMessageType(op.Output.Message, true)
			_ = g.resolveMessageType(op.Input.Message, true)
		}
	}
	// Global pass: output, input, input per operation.
	for _, pt := range g.defs.PortTypes {
		for _, op := range pt.Operations {
			_ = g.resolveMessageType(op.Output.Message, true)
			_ = g.resolveMessageType(op.Input.Message, true)
			_ = g.resolveMessageType(op.Input.Message, true)
		}
	}
	// Two per-port passes: input then output.
	for _, pt := range g.defs.PortTypes {
		for pass := 0; pass < 2; pass++ {
			for _, op := range pt.Operations {
				_ = g.resolveMessageType(op.Input.Message, true)
				_ = g.resolveMessageType(op.Output.Message, true)
			}
		}
	}
}

type resolvedOp struct {
	name       string
	request    string
	response   string
	soapAction string
	doc        string
	faults     []string
}

type resolvedPort struct {
	iface   string
	private string
	ops     []*resolvedOp
}

func (g *generator) soapActionFor(portName string, opName string) string {
	for _, b := range g.defs.Bindings {
		if stripQName(b.Type) != portName {
			continue
		}
		for _, bop := range b.Operations {
			if bop.Name != opName {
				continue
			}
			action := ""
			if bop.SoapOperation != nil {
				action = bop.SoapOperation.SoapAction
			}
			if action == "" {
				return "''"
			}
			return action
		}
	}
	return "''"
}

func (g *generator) buildOperations() {
	for _, pt := range g.defs.PortTypes {
		rp := &resolvedPort{
			iface:   g.portInterfaceName(pt.Name),
			private: lowerFirst(pt.Name),
		}
		for _, op := range pt.Operations {
			rop := &resolvedOp{
				name:       g.opMethodName(op.Name),
				request:    g.declaredName(g.resolveMessageType(op.Input.Message, false)),
				response:   g.declaredName(g.resolveMessageType(op.Output.Message, false)),
				soapAction: g.soapActionFor(pt.Name, op.Name),
				doc:        op.Documentation,
			}
			for _, f := range op.Faults {
				rop.faults = append(rop.faults, f.Name)
			}
			rp.ops = append(rp.ops, rop)
			g.allOps = append(g.allOps, rop)
		}
		g.ports = append(g.ports, rp)
	}
}

// --- XMLName determination for named complex types ---

func (g *generator) computeXMLNames() {
	cands := make(map[string]map[string]bool)
	add := func(typeName string, elName string) {
		if cands[typeName] == nil {
			cands[typeName] = make(map[string]bool)
		}
		cands[typeName][elName] = true
	}
	var walkElement func(el *XElement)
	var walkComplex func(ct *ComplexType)
	var walkExtension func(ext *Extension)
	walkElement = func(el *XElement) {
		if el.Type != "" {
			add(stripQName(el.Type), el.Name)
		}
		if el.ComplexType != nil {
			walkComplex(el.ComplexType)
		}
	}
	walkElements := func(els []*XElement) {
		for _, el := range els {
			walkElement(el)
		}
	}
	walkExtension = func(ext *Extension) {
		if ext == nil {
			return
		}
		for _, seq := range ext.Sequences {
			walkElements(seq.Elements)
		}
		for _, ch := range ext.Choices {
			walkElements(ch.Elements)
		}
		for _, seq := range ext.Sequences {
			for _, ch := range seq.Choices {
				walkElements(ch.Elements)
			}
		}
	}
	walkComplex = func(ct *ComplexType) {
		if ct == nil {
			return
		}
		for _, seq := range ct.Sequences {
			walkElements(seq.Elements)
		}
		for _, ch := range ct.Choices {
			walkElements(ch.Elements)
		}
		for _, all := range ct.Alls {
			walkElements(all.Elements)
		}
		for _, seq := range ct.Sequences {
			for _, ch := range seq.Choices {
				walkElements(ch.Elements)
			}
		}
		if ct.ComplexContent != nil {
			walkExtension(ct.ComplexContent.Extension)
		}
		if ct.SimpleContent != nil {
			walkExtension(ct.SimpleContent.Extension)
		}
	}
	for _, sch := range g.schemas {
		for _, el := range sch.Elements {
			walkElement(el)
		}
		for _, ct := range sch.ComplexTypes {
			walkComplex(ct)
		}
	}
	for _, sch := range g.schemas {
		for _, ct := range sch.ComplexTypes {
			if set, ok := cands[ct.Name]; ok && len(set) == 1 {
				for name := range set {
					g.xmlNames[ct] = name
				}
			}
		}
	}
}
