func simpleAliasType(st *SimpleType) string {
	if st.List != nil && st.List.ItemType != "" {
		return "[]" + plainGoType(st.List.ItemType)
	}
	if st.Restriction != nil && st.Restriction.Base != "" {
		return plainGoType(st.Restriction.Base)
	}
	if st.Union != nil && (st.Union.MemberTypes != "" || len(st.Union.SimpleTypes) > 0) {
		return "string"
	}
