func (g *generator) renderEnumerationConsts(typeName string, st *SimpleType) string {
	if st == nil || st.Restriction == nil || len(st.Restriction.Enumerations) == 0 {
		return ""
	}
	var entries []block
	for _, e := range st.Restriction.Enumerations {
		name := typeName + g.declaredName(e.Value)
		val := strings.ReplaceAll(e.Value, "\"", "\\\"")
		line := name + " " + typeName + " = \"" + val + "\""
		doc := formatDoc(annotationDoc(e.Annotation))
		if doc != "" {
			entries = append(entries, block{text: doc + "\n" + line, hasDoc: true})
		} else {
			entries = append(entries, block{text: line})
		}
	}
	var sb strings.Builder
	sb.WriteString("const (\n")
	if len(entries) > 0 && entries[0].hasDoc {
		sb.WriteString("\n")
