func (g *generator) renderSimpleType(st *SimpleType) string {
	name := g.declaredName(st.Name)
	var sb strings.Builder
	if doc := formatDoc(annotationDoc(st.Annotation)); doc != "" {
		sb.WriteString(doc + "\n\n")
	}
	sb.WriteString("type " + name + " " + simpleAliasType(st))
