var dateMethods = map[string][2]string{
	"soap.XSDDateTime": {"xdt", "soap.XSDDateTime"},
	"soap.XSDDate":     {"xd", "soap.XSDDate"},
	"soap.XSDTime":     {"xt", "soap.XSDTime"},
}

func (g *generator) renderGlobalElement(el *XElement, sch *Schema) string {
	if el.Type != "" {
		name := g.declaredName(el.Name)
		plain := plainGoType(el.Type)
		if name == plain {
			return ""
		}
		out := "type " + name + " " + plain
		if info, ok := dateMethods[plain]; ok {
			recv, soapType := info[0], info[1]
			out += "\n\nfunc (" + recv + " " + name + ") MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n" +
				"return " + soapType + "(" + recv + ").MarshalXML(e, start)\n}"
			out += "\n\nfunc (" + recv + " *" + name + ") UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n" +
				"return (*" + soapType + ")(" + recv + ").UnmarshalXML(d, start)\n}"
		}
		return out
	}
	if el.SimpleType != nil {
		name := g.declaredName(el.Name)
		var sb strings.Builder
		if doc := formatDoc(annotationDoc(el.SimpleType.Annotation)); doc != "" {
			sb.WriteString(doc + "\n\n")
		}
		sb.WriteString("type " + name + " " + simpleAliasType(el.SimpleType))
		if consts := g.renderEnumerationConsts(name, el.SimpleType); consts != "" {
			sb.WriteString("\n\n" + consts)
		}
		return sb.String()
	}
	if el.ComplexType != nil {
		name := g.declaredName(el.Name)
		blocks := []block{{text: "XMLName xml.Name `xml:\"" + sch.TargetNamespace + " " + el.Name + "\"`"}}
		blocks = append(blocks, g.complexBodyBlocks(el.ComplexType, sch)...)
		return renderStruct(name, blocks)
	}
	return ""
}

func isStringAlias(ct *ComplexType) bool {
	if ct.SimpleContent == nil || ct.SimpleContent.Extension == nil {
		return false
	}
	ext := ct.SimpleContent.Extension
	if len(ext.Attributes) != 0 {
		return false
	}
	return plainGoType(ext.Base) == "string"
}

func (g *generator) renderComplexType(ct *ComplexType, sch *Schema) string {
	name := g.declaredName(ct.Name)
	if isStringAlias(ct) {
		return "type " + name + " string"
	}
	var blocks []block
	if elName, ok := g.xmlNames[ct]; ok {
		blocks = append(blocks, block{text: "XMLName xml.Name `xml:\"" + sch.TargetNamespace + " " + elName + "\"`"})
	}
	blocks = append(blocks, g.complexBodyBlocks(ct, sch)...)
	return renderStruct(name, blocks)
}

func extensionBase(ext *Extension) string {
	if ext == nil {
		return ""
	}
	return ext.Base
}

func (g *generator) complexBodyBlocks(ct *ComplexType, sch *Schema) []block {
	var blocks []block
	ccBase := ""
	if ct.ComplexContent != nil {
		ccBase = extensionBase(ct.ComplexContent.Extension)
	}
	scBase := ""
	if ct.SimpleContent != nil {
		scBase = extensionBase(ct.SimpleContent.Extension)
	}
	if ccBase != "" {
		ext := ct.ComplexContent.Extension
		blocks = append(blocks, block{text: fieldGoTypeNoOcc(ext.Base)})
		for _, seq := range ext.Sequences {
			for _, el := range seq.Elements {
				blocks = append(blocks, g.elementField(el, sch))
			}
		}
		for _, ch := range ext.Choices {
			for _, el := range ch.Elements {
				blocks = append(blocks, g.elementField(el, sch))
			}
		}
		for _, seq := range ext.Sequences {
			for _, ch := range seq.Choices {
				for _, el := range ch.Elements {
					blocks = append(blocks, g.elementField(el, sch))
				}
			}
		}
		for _, at := range ext.Attributes {
			blocks = append(blocks, g.attributeField(at, sch))
		}
		return blocks
	}
	if scBase != "" {
		ext := ct.SimpleContent.Extension
		blocks = append(blocks, block{text: "Value " + fieldGoTypeNoOcc(ext.Base) + " `xml:\",chardata\" json:\"-,\"`"})
		for _, at := range ext.Attributes {
			blocks = append(blocks, g.attributeField(at, sch))
		}
		return blocks
	}
	for _, seq := range ct.Sequences {
		for _, el := range seq.Elements {
			blocks = append(blocks, g.elementField(el, sch))
		}
	}
	for _, seq := range ct.Sequences {
		for range seq.Anys {
			blocks = append(blocks, block{text: "Items []string `xml:\",any\" json:\"items,omitempty\"`"})
		}
	}
	for _, ch := range ct.Choices {
		for _, el := range ch.Elements {
			blocks = append(blocks, g.elementField(el, sch))
		}
	}
	for _, seq := range ct.Sequences {
		for _, ch := range seq.Choices {
			for _, el := range ch.Elements {
				blocks = append(blocks, g.elementField(el, sch))
			}
		}
	}
	for _, all := range ct.Alls {
		for _, el := range all.Elements {
			blocks = append(blocks, g.elementField(el, sch))
		}
	}
	for _, at := range ct.Attributes {
		blocks = append(blocks, g.attributeField(at, sch))
	}
	return blocks
}

func inlineSimpleFieldType(st *SimpleType) string {
	if st.List != nil && st.List.ItemType != "" {
		return "[]" + fieldGoTypeNoOcc(st.List.ItemType)
	}
	if st.Restriction != nil {
		return fieldGoTypeNoOcc(st.Restriction.Base)
	}
	return fieldGoTypeNoOcc("")
}

func (g *generator) elementField(el *XElement, sch *Schema) block {
	if el.Ref != "" {
		local := stripQName(el.Ref)
		name := g.declaredName(local)
		goType := fieldGoType(el.Ref, el.Nillable, el.MaxOccurs)
		return block{text: name + " " + goType + " `xml:\"" + local + ",omitempty\" json:\"" + local + ",omitempty\"`"}
	}
	tag := " `xml:\"" + el.Name + ",omitempty\" json:\"" + el.Name + ",omitempty\"`"
	if el.Type != "" {
		name := typedFieldName(el.Name)
		line := name + " " + fieldGoType(el.Type, el.Nillable, el.MaxOccurs) + tag
		if doc := formatDoc(annotationDoc(el.Annotation)); doc != "" {
			return block{text: doc + "\n" + line, hasDoc: true}
		}
		return block{text: line}
	}
	if el.SimpleType != nil {
		name := declaredPublic(el.Name)
		line := name + " " + inlineSimpleFieldType(el.SimpleType) + tag
		if doc := formatDoc(annotationDoc(el.Annotation)); doc != "" {
			return block{text: doc + "\n\n" + line, hasDoc: true}
		}
		return block{text: line}
	}
	// Inline complex type (or no type at all): anonymous struct.
	name := g.declaredName(el.Name)
	var inner []block
	if el.ComplexType != nil {
		inner = g.complexBodyBlocks(el.ComplexType, sch)
	}
	prefix := ""
	if el.MaxOccurs == "unbounded" {
		prefix = "[]"
	}
	return block{text: name + " " + prefix + renderAnonymousStruct(inner) + tag}
}

func attributeGoType(at *XAttribute) string {
	if at.Type != "" {
		return fieldGoTypeNoOcc(at.Type)
	}
	if at.SimpleType != nil && at.SimpleType.Restriction != nil && at.SimpleType.Restriction.Base != "" {
		return fieldGoTypeNoOcc(at.SimpleType.Restriction.Base)
	}
	return "string"
}

func (g *generator) attributeField(at *XAttribute, sch *Schema) block {
	origName := at.Name
	goType := ""
	if at.Ref != "" {
		resolved := g.findGlobalAttribute(stripQName(at.Ref))
		if resolved == nil {
			origName = ""
			goType = "string"
		} else {
			origName = stripQName(at.Ref)
			goType = attributeGoType(resolved)
		}
	} else {
		goType = attributeGoType(at)
	}
	name := attrFieldName(origName)
	nsPrefix := ""
	if sch.TargetNamespace != "" {
		nsPrefix = sch.TargetNamespace + " "
	}
	line := name + " " + goType + " `xml:\"" + nsPrefix + origName + ",attr,omitempty\" json:\"" + origName + ",omitempty\"`"
	if doc := formatDoc(annotationDoc(at.Annotation)); doc != "" {
		return block{text: doc + "\n\n" + line, hasDoc: true}
	}
	return block{text: line}
}

func (op *resolvedOp) params(context bool) string {
	var parts []string
	if context {
		parts = append(parts, "ctx context.Context")
	}
	if op.request != "" {
		parts = append(parts, "request *"+op.request)
	}
	return strings.Join(parts, ", ")
}

func (op *resolvedOp) returns() string {
	if op.response != "" {
		return "(*" + op.response + ", error)"
	}
	return "error"
}

func (g *generator) renderPorts() []string {
	var decls []string
	for _, port := range g.ports {
		var sb strings.Builder
		sb.WriteString("type " + port.iface + " interface {\n")
		if len(port.ops) > 0 {
			first := port.ops[0]
			if len(first.faults) > 0 || first.doc != "" {
				sb.WriteString("\n")
			}
			for i, op := range port.ops {
				if i > 0 {
					sb.WriteString("\n\n")
				}
				if len(op.faults) > 0 {
					sb.WriteString("// Error can be either of the following types:\n//\n")
					for _, f := range op.faults {
						sb.WriteString("//   - " + f + "\n")
					}
					if op.doc == "" {
						sb.WriteString("\n")
					}
				}
				if op.doc != "" {
					sb.WriteString("/* " + op.doc + " */\n")
				}
				sb.WriteString(op.name + "(" + op.params(false) + ") " + op.returns())
				sb.WriteString("\n\n")
				sb.WriteString(op.name + "Context(" + op.params(true) + ") " + op.returns())
			}
			sb.WriteString("\n")
		}
		sb.WriteString("}")
		decls = append(decls, sb.String())

		decls = append(decls, "type "+port.private+" struct {\nclient *soap.Client\n}")
		decls = append(decls, "func New"+port.iface+"(client *soap.Client) "+port.iface+" {\nreturn &"+port.private+"{\nclient: client,\n}\n}")

		for _, op := range port.ops {
			reqArg := "nil"
			if op.request != "" {
				reqArg = "request"
			}
			var cb strings.Builder
			cb.WriteString("func (service *" + port.private + ") " + op.name + "Context(" + op.params(true) + ") " + op.returns() + " {\n")
			if op.response != "" {
				cb.WriteString("response := new(" + op.response + ")\n")
				cb.WriteString("err := service.client.CallContext(ctx, \"" + op.soapAction + "\", " + reqArg + ", response)\n")
				cb.WriteString("if err != nil {\nreturn nil, err\n}\n\nreturn response, nil\n}")
			} else {
				cb.WriteString("\nerr := service.client.CallContext(ctx, \"" + op.soapAction + "\", " + reqArg + ", struct{}{})\n")
				cb.WriteString("if err != nil {\nreturn err\n}\n\nreturn nil\n}")
			}
			decls = append(decls, cb.String())

			var nb strings.Builder
			nb.WriteString("func (service *" + port.private + ") " + op.name + "(" + op.params(false) + ") " + op.returns() + " {\n")
			nb.WriteString("return service." + op.name + "Context(\ncontext.Background(),\n")
			if op.request != "" {
				nb.WriteString("request,\n")
			}
			nb.WriteString(")\n}")
			decls = append(decls, nb.String())
		}
	}
	return decls
}

func (g *generator) clientSource() []byte {
	var decls []string
	decls = append(decls, "type AnyType struct {\nInnerXML string `xml:\",innerxml\"`\n}")
	decls = append(decls, "type AnyURI string")
	decls = append(decls, "type NCName string")
	for _, sch := range g.schemas {
		for _, st := range sch.SimpleTypes {
			decls = append(decls, g.renderSimpleType(st))
		}
		for _, el := range sch.Elements {
			if s := g.renderGlobalElement(el, sch); s != "" {
				decls = append(decls, s)
			}
		}
		for _, ct := range sch.ComplexTypes {
			decls = append(decls, g.renderComplexType(ct, sch))
		}
	}
	decls = append(decls, g.renderPorts()...)

	var sb strings.Builder
	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\npackage " + g.pkg + "\n\n")
	sb.WriteString("import (\n\"context\"\n\"encoding/xml\"\n\"github.com/hooklift/gowsdl/soap\"\n\"time\"\n)\n\n")
	sb.WriteString("// against \"unused imports\"\nvar _ time.Time\nvar _ xml.Name\n")
	for _, d := range decls {
		sb.WriteString("\n" + d + "\n")
	}
	return []byte(sb.String())
}

func writeFormatted(path string, raw []byte) error {
	if err := os.WriteFile(path, raw, 0644); err != nil {
		return err
	}
	formatted, err := format.Source(raw)
	if err != nil {
		return err
	}
	return os.WriteFile(path, formatted, 0644)
}

func (g *generator) generate(outputDir string, outputFile string) error {
	dir := filepath.Join(outputDir, g.pkg)
	_ = os.Mkdir(dir, 0744)
	clientPath := filepath.Join(dir, outputFile)
	if err := writeFormatted(clientPath, g.clientSource()); err != nil {
		return err
	}
	serverPath := filepath.Join(dir, "server"+outputFile)
	if err := writeFormatted(serverPath, g.serverSource()); err != nil {
		return err
	}
	return nil
}
