	tag := " `xml:\"" + el.Name + ",omitempty\" json:\"" + el.Name + ",omitempty\"`"
	if el.Type != "" {
		name := typedFieldName(el.Name)
		line := name + " " + fieldGoType(el.Type, el.Nillable, el.MaxOccurs) + tag
