		sb.WriteString("type " + port.iface + " interface {\n")
		if len(port.ops) > 0 {
			first := port.ops[0]
			if len(first.faults) > 0 || first.doc != "" {
				sb.WriteString("\n")
			}
			for i, op := range port.ops {
				if i > 0 {
					sb.WriteString("\n\n")
				}
				if len(op.faults) > 0 {
					sb.WriteString("// Error can be either of the following types:\n//\n")
					for _, f := range op.faults {
						sb.WriteString("//   - " + f + "\n")
					}
					if op.doc == "" {
						sb.WriteString("\n")
					}
				}
				if op.doc != "" {
					sb.WriteString("/* " + op.doc + " */\n")
				}
				sb.WriteString(op.name + "(" + op.params(false) + ") " + op.returns())
				sb.WriteString("\n\n")
				sb.WriteString(op.name + "Context(" + op.params(true) + ") " + op.returns())
			}
			sb.WriteString("\n")
		}
		sb.WriteString("}")
		decls = append(decls, sb.String())

		decls = append(decls, "type "+port.private+" struct {\nclient *soap.Client\n}")
		decls = append(decls, "func New"+port.iface+"(client *soap.Client) "+port.iface+" {\nreturn &"+port.private+"{\nclient: client,\n}\n}")

		for _, op := range port.ops {
			reqArg := "nil"
			if op.request != "" {
				reqArg = "request"
			}
			var cb strings.Builder
			cb.WriteString("func (service *" + port.private + ") " + op.name + "Context(" + op.params(true) + ") " + op.returns() + " {\n")
			if op.response != "" {
				cb.WriteString("response := new(" + op.response + ")\n")
				cb.WriteString("err := service.client.CallContext(ctx, \"" + op.soapAction + "\", " + reqArg + ", response)\n")
				cb.WriteString("if err != nil {\nreturn nil, err\n}\n\nreturn response, nil\n}")
			} else {
				cb.WriteString("\nerr := service.client.CallContext(ctx, \"" + op.soapAction + "\", " + reqArg + ", struct{}{})\n")
				cb.WriteString("if err != nil {\nreturn err\n}\n\nreturn nil\n}")
			}
			decls = append(decls, cb.String())

			var nb strings.Builder
			nb.WriteString("func (service *" + port.private + ") " + op.name + "(" + op.params(false) + ") " + op.returns() + " {\n")
			nb.WriteString("return service." + op.name + "Context(\ncontext.Background(),\n")
			if op.request != "" {
				nb.WriteString("request,\n")
			}
			nb.WriteString(")\n}")
			decls = append(decls, nb.String())
		}
	}
	return decls
}

func (g *generator) clientSource() []byte {
	var decls []string
	decls = append(decls, "type AnyType struct {\nInnerXML string `xml:\",innerxml\"`\n}")
	decls = append(decls, "type AnyURI string")
	decls = append(decls, "type NCName string")
	for _, sch := range g.schemas {
		for _, st := range sch.SimpleTypes {
			decls = append(decls, g.renderSimpleType(st))
		}
		for _, el := range sch.Elements {
			if s := g.renderGlobalElement(el, sch); s != "" {
				decls = append(decls, s)
			}
		}
		for _, ct := range sch.ComplexTypes {
			decls = append(decls, g.renderComplexType(ct, sch))
		}
	}
	decls = append(decls, g.renderPorts()...)

	var sb strings.Builder
	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\npackage " + g.pkg + "\n\n")
	sb.WriteString("import (\n\"context\"\n\"encoding/xml\"\n\"github.com/hooklift/gowsdl/soap\"\n\"time\"\n)\n\n")
	sb.WriteString("// against \"unused imports\"\nvar _ time.Time\nvar _ xml.Name\n")
	for _, d := range decls {
		sb.WriteString("\n" + d + "\n")
	}
	return []byte(sb.String())
}

func writeFormatted(path string, raw []byte) error {
	if err := os.WriteFile(path, raw, 0644); err != nil {
		return err
	}
	formatted, err := format.Source(raw)
	if err != nil {
		return err
	}
	return os.WriteFile(path, formatted, 0644)
}

func (g *generator) generate(outputDir string, outputFile string) error {
	dir := filepath.Join(outputDir, g.pkg)
	_ = os.Mkdir(dir, 0744)
	clientPath := filepath.Join(dir, outputFile)
	if err := writeFormatted(clientPath, g.clientSource()); err != nil {
		return err
	}
	serverPath := filepath.Join(dir, "server"+outputFile)
	if err := writeFormatted(serverPath, g.serverSource()); err != nil {
		return err
	}
	return nil
}
