package main

import (
	"go/format"
	"os"
	"strings"
)

// The reference output preserves blank lines (rendered as "//") at the
// start/end of documentation comments. Modern gofmt versions normalise
// doc comments and drop those. To preserve them, line-comment groups
// that are directly attached to the following declaration are briefly
// detached with a sentinel line before formatting, and restored after.

func protectLineComments(raw []byte) ([]byte, string) {
	marker := "__wsdlgen_keep_comment__"
	for strings.Contains(string(raw), marker) {
		marker += "_x"
	}
	lines := strings.Split(string(raw), "\n")
	var out []string
	inBlock := false
	for i := 0; i < len(lines); {
		line := lines[i]
		trimmed := strings.TrimSpace(line)
		if !inBlock && strings.HasPrefix(trimmed, "//") {
			// Copy a whole comment group.
			startIndent := line[:len(line)-len(strings.TrimLeft(line, " \t"))]
			j := i
			for j < len(lines) && strings.HasPrefix(strings.TrimSpace(lines[j]), "//") {
				out = append(out, lines[j])
				j++
			}
			if j < len(lines) {
				next := strings.TrimSpace(lines[j])
				if next != "" && next != "}" {
					out = append(out, startIndent+"// "+marker)
					out = append(out, "")
				}
			}
			i = j
			continue
		}
		out = append(out, line)
		// Track block comments crudely (generated block comments are
		// operation documentation; a line here never contains a
		// string literal containing /* outside a struct tag handled
		// on one line).
		if inBlock {
			if strings.Contains(line, "*/") {
				inBlock = false
			}
		} else if strings.HasPrefix(trimmed, "/*") && !strings.Contains(line, "*/") {
			inBlock = true
		}
		i++
	}
	return []byte(strings.Join(out, "\n")), marker
}

func unprotectLineComments(formatted []byte, marker string) []byte {
	lines := strings.Split(string(formatted), "\n")
	var out []string
	for i := 0; i < len(lines); i++ {
		if strings.TrimSpace(lines[i]) == "// "+marker {
			if i+1 < len(lines) && strings.TrimSpace(lines[i+1]) == "" {
				i++ // drop the blank line we inserted
			}
			continue
		}
		out = append(out, lines[i])
	}
	return []byte(strings.Join(out, "\n"))
}

func writeFormattedFile(path string, raw []byte, protect bool) error {
	if err := os.WriteFile(path, raw, 0644); err != nil {
		return err
	}
	toFormat := raw
	marker := ""
	if protect {
		toFormat, marker = protectLineComments(raw)
	}
	formatted, err := format.Source(toFormat)
	if err != nil {
		return err
	}
	if protect {
		formatted = unprotectLineComments(formatted, marker)
	}
	return os.WriteFile(path, formatted, 0644)
}
